// src/app/impressum/page.js
//
// Impressum der ÖkoInvest GmbH nach österreichischem Recht:
//  - § 5 E-Commerce-Gesetz (ECG)       Diensteanbieter-Informationen
//  - § 14 Unternehmensgesetzbuch (UGB) Angaben auf Geschäftspapieren/Websites
//  - § 25 Mediengesetz (MedienG)        Offenlegung
// Alle Stammdaten kommen aus src/data/site.js (GESELLSCHAFT, KONTAKT).
//
// TODO vor Livegang (fachlich/rechtlich zu ergänzen, bewusst NICHT im Text):
//  - UID-Nummer: GESELLSCHAFT.uid ist noch null -> Zeile erscheint automatisch,
//    sobald sie eingetragen ist.
//  - Kammerzugehörigkeit (voraussichtlich Wirtschaftskammer Oberösterreich) und
//    Fachgruppe prüfen und ergänzen (§ 5 Abs. 1 Z 5 ECG).
//  - Gewerbe/Berufsrecht und zuständige Aufsichtsbehörde (Gewerbebehörde,
//    voraussichtlich Bezirkshauptmannschaft Braunau am Inn) prüfen und ergänzen
//    (§ 5 Abs. 1 Z 4 und 6 ECG) – nur, wenn eine Gewerbeberechtigung besteht.
//  - Beteiligungsverhältnisse (Gesellschafter mit Anteilen) nach § 25 Abs. 2
//    MedienG aus dem aktuellen Firmenbuchauszug ergänzen.
//  - Telefon/E-Mail: erscheinen automatisch, sobald KONTAKT freigegeben ist.
//    § 5 Abs. 1 Z 3 ECG verlangt Angaben, die eine rasche und unmittelbare
//    Kontaktaufnahme ermöglichen, einschließlich E-Mail-Adresse -> vor
//    Livegang zwingend freigeben.
//  - Verbraucherschlichtung: Teilnahmebereitschaft (AStG) rechtlich festlegen.

import Link from "next/link";
import LegalShell from "@/components/Reusable/LegalShell";
import { GESELLSCHAFT, KONTAKT, SITE, abs } from "@/data/site";

const PAGE_URL = abs("/impressum");
const TITEL = "Impressum | ÖkoInvest";
const BESCHREIBUNG =
  "Impressum und Offenlegung der ÖkoInvest GmbH, Ostermiething (Österreich): Firmenbuch, Geschäftsführung, Unternehmensgegenstand und Angaben nach ECG, UGB und MedienG.";

export const metadata = {
  title: TITEL,
  description: BESCHREIBUNG,
  alternates: { canonical: PAGE_URL },
  robots: { index: true, follow: true },
  openGraph: {
    type: "website",
    locale: "de_AT",
    url: PAGE_URL,
    siteName: "ÖkoInvest",
    title: TITEL,
    description: BESCHREIBUNG,
    images: [{ url: abs("/img/firmensitz.jpg"), alt: "Firmensitz der ÖkoInvest GmbH" }],
  },
};

const G = GESELLSCHAFT;

export default function ImpressumPage() {
  return (
    <LegalShell
      titel="Impressum"
      pfad="/impressum"
      lead="Informationen nach § 5 E-Commerce-Gesetz und § 14 Unternehmensgesetzbuch sowie Offenlegung nach § 25 Mediengesetz."
    >
      <h2>Diensteanbieter und Medieninhaber</h2>
      <div className="not-prose mt-5 grid gap-4 sm:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
        <address className="relative overflow-hidden rounded-2xl bg-sand-50 p-5 not-italic ring-1 ring-ink-200/70 md:p-6">
          <span aria-hidden="true" className="absolute inset-y-0 left-0 w-1 bg-gradient-to-b from-ov-500 to-ov-300" />
          <strong className="font-display text-[17px]">{G.name}</strong>
          <br />
          {G.sitz}
          <br />
          {G.plz} {G.ort}
          <br />
          {G.land}
        </address>
        <div className="rounded-2xl bg-sand-50 p-5 ring-1 ring-ink-200/70 md:p-6">
          <h2 className="!mt-0 !mb-2 !text-[17px]">Kontakt</h2>
          {KONTAKT.telefon && (
            <p>
              Telefon: <a href={KONTAKT.telefonHref || `tel:${KONTAKT.telefon.replace(/[^+\d]/g, "")}`}>{KONTAKT.telefon}</a>
            </p>
          )}
          {KONTAKT.email && (
            <p>
              E-Mail: <a href={`mailto:${KONTAKT.email}`}>{KONTAKT.email}</a>
            </p>
          )}
          <p>
            Sie erreichen uns schriftlich über das <Link href="/kontakt">Kontaktformular</Link> oder – nach Registrierung – über die
            Nachrichtenfunktion im Portal. Die Postanschrift finden Sie oben.
          </p>
        </div>
      </div>

      <h2>Unternehmensangaben</h2>
      <dl className="mt-5 grid gap-px overflow-hidden rounded-2xl bg-ink-200/70 ring-1 ring-ink-200/70 sm:grid-cols-2">
        {[
          ["Firma und Rechtsform", `${G.name}, Gesellschaft mit beschränkter Haftung`],
          ["Sitz", `${G.ort}, ${G.land}`],
          ["Firmenbuchnummer", G.register],
          ["Firmenbuchgericht", G.gericht],
          ...(G.uid ? [["UID-Nummer", G.uid]] : []),
          ["Geschäftsführung", G.geschaeftsfuehrung.join(", ")],
          ["Unternehmensgegenstand", G.gegenstand, true],
        ].map(([dt, dd, breit]) => (
          <div key={dt} className={`bg-white px-5 py-4 ${breit ? "sm:col-span-2" : ""}`}>
            <dt className="text-[12.5px] font-semibold uppercase tracking-[0.1em] text-ink-500">{dt}</dt>
            <dd className="mt-1 font-medium leading-relaxed text-ink-900">{dd}</dd>
          </div>
        ))}
      </dl>

      <h2>Offenlegung nach § 25 Mediengesetz</h2>
      <p>
        <strong>Medieninhaber:</strong> {G.name}, {G.sitz}, {G.plz} {G.ort}, {G.land}.
      </p>
      <p>
        <strong>Unternehmensgegenstand:</strong> {G.gegenstand}.
      </p>
      <p>
        <strong>Geschäftsführung:</strong> {G.geschaeftsfuehrung.join(", ")}.
      </p>
      <p>
        Die {G.name} ist Teil der {SITE.gruppe}.
        {G.beteiligungen?.length > 0 && (
          <>
            {" "}
            Beteiligungen der Gesellschaft:{" "}
            {G.beteiligungen.map((b, i) => (
              <span key={b.name}>
                {i > 0 && "; "}
                {b.name} ({b.register}, {b.anteil})
              </span>
            ))}
            .
          </>
        )}
      </p>
      <p>
        <strong>Grundlegende Richtung:</strong> Information über Projektentwicklung, Planung, Finanzierung und Betrieb von Photovoltaik-Kraftwerken
        (Freifläche, Agri-PV, Solarcarports) und Großspeichern, über die Projektbörse und die Investoren-Plattform sowie über Stromlieferung,
        virtuelle Kraftwerke und Energiegemeinschaften in Deutschland, Österreich und der Schweiz.
      </p>

      <h2>Online-Streitbeilegung und Verbraucherschlichtung</h2>
      <p>
        Die frühere Plattform der Europäischen Kommission zur Online-Streitbeilegung (OS-Plattform) wurde durch die Verordnung (EU) 2024/3228
        mit Wirkung zum 20. Juli 2025 eingestellt; ein Hinweis darauf ist daher nicht mehr vorgesehen. Unsere Angebote richten sich überwiegend
        an Unternehmen, Landwirte, Kommunen und Investoren. Zur Teilnahme an einem Streitbeilegungsverfahren vor einer
        Verbraucherschlichtungsstelle sind wir nicht verpflichtet und nehmen daran grundsätzlich nicht teil. Anliegen klären wir gern direkt mit
        Ihnen.
      </p>

      <h2>Haftung für Inhalte</h2>
      <p>
        Wir erstellen die Inhalte dieser Website mit Sorgfalt. Ratgeber, Lexikon, Rechner und Marktdaten dienen der allgemeinen Information und
        geben Orientierungswerte mit dem jeweils angegebenen Stand wieder. Sie ersetzen keine Rechts-, Steuer- oder Anlageberatung und kein
        verbindliches Angebot. Für Richtigkeit, Vollständigkeit und Aktualität übernehmen wir – soweit gesetzlich zulässig – keine Gewähr.
      </p>
      <p>
        Angaben zu Projekten in der <Link href="/projektboerse">Projektbörse</Link> stammen von den jeweiligen Anbietern. Ergänzend gelten unsere{" "}
        <Link href="/nutzungsbedingungen">Nutzungsbedingungen</Link>.
      </p>

      <h2>Haftung für Links</h2>
      <p>
        Unsere Website enthält Verweise auf Websites Dritter, auf deren Inhalte wir keinen Einfluss haben. Für diese Inhalte ist der jeweilige
        Anbieter verantwortlich. Zum Zeitpunkt der Verlinkung waren keine Rechtsverstöße erkennbar. Werden uns Rechtsverletzungen bekannt,
        entfernen wir die betreffenden Links umgehend (§ 17 ECG).
      </p>

      <h2>Urheberrecht</h2>
      <p>
        Texte, Grafiken, Rechner und Fotos dieser Website sind urheberrechtlich geschützt. Eine Verwendung außerhalb der Grenzen des
        Urheberrechts bedarf unserer vorherigen schriftlichen Zustimmung. Kurze Zitate mit Quellenangabe und Link sind willkommen.
      </p>

      <h2>Weitere Rechtstexte</h2>
      <p>
        <Link href="/datenschutz">Datenschutzerklärung</Link> · <Link href="/nutzungsbedingungen">Nutzungsbedingungen</Link> ·{" "}
        <Link href="/barrierefreiheit">Erklärung zur Barrierefreiheit</Link>
      </p>
    </LegalShell>
  );
}

// src/app/bedingungen/_teile.js
//
// Gemeinsame Bausteine der Besonderen Bedingungen (/bedingungen/*).
// Datei mit Unterstrich = kein Route-Segment. Alle Seiten sind ENTWÜRFE zur
// anwaltlichen Prüfung und stehen bis zur Freigabe auf noindex
// (FREIGEGEBEN = true setzen, sobald die Fassungen geprüft sind; dann
// zusätzlich in Sitemap und Footer aufnehmen – Koordinator).

import Link from "next/link";
import { AlertTriangle } from "lucide-react";
import { abs } from "@/data/site";

export const FREIGEGEBEN = false;

/** Stand der Entwürfe */
export const STAND_BEDINGUNGEN = "30. September 2026";

export const BEDINGUNGEN = [
  { href: "/bedingungen/projektboerse", titel: "Besondere Bedingungen Projektbörse", kurz: "Projektbörse" },
  { href: "/bedingungen/energiebeschaffung", titel: "Servicevertrag Energiebeschaffung", kurz: "Energiebeschaffung" },
  { href: "/bedingungen/lieferanten", titel: "Teilnahmebedingungen für Energieversorger", kurz: "Energieversorger" },
  { href: "/bedingungen/banken", titel: "Vertraulichkeitsbedingungen für Banken", kurz: "Banken" },
];

/** Metadaten je Bedingungsseite – noindex bis zur Freigabe. */
export function bedingungenMetadata({ pfad, titel, beschreibung, bild = "/img/solarpark-himmel.jpg", bildAlt = "Solarpark unter blauem Himmel" }) {
  const url = abs(pfad);
  return {
    title: titel,
    description: beschreibung,
    alternates: { canonical: url },
    robots: FREIGEGEBEN ? { index: true, follow: true } : { index: false, follow: false },
    openGraph: {
      type: "website",
      locale: "de_AT",
      url,
      siteName: "ÖkoInvest",
      title: titel,
      description: beschreibung,
      images: [{ url: abs(bild), alt: bildAlt }],
    },
  };
}

/** Sichtbar markierter Platzhalter – vor Freigabe ersetzen. */
export function Platzhalter({ children }) {
  return <mark className="rounded-md bg-sun-300/40 px-1.5 py-0.5 font-semibold text-ink-900">[Platzhalter: {children}]</mark>;
}

/** Entwurfs-Hinweis oben auf jeder Seite (als aside, damit .ov-legal die Innenabstände nicht zurücksetzt). */
export function EntwurfHinweis({ children }) {
  if (FREIGEGEBEN) return null;
  return (
    <aside role="note" className="mb-10 flex gap-4 rounded-2xl bg-sun-300/20 p-5 ring-1 ring-sun-300/60 md:p-6">
      <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-sun-400 text-navy-950">
        <AlertTriangle aria-hidden="true" className="h-[18px] w-[18px]" />
      </span>
      <div>
        <p className="font-display text-[16.5px] font-bold text-ink-900">Entwurf – anwaltlich zu prüfen</p>
        <p className="mt-1.5 text-[15.5px] leading-relaxed text-ink-700">
          {children ||
            "Diese Bedingungen sind ein Entwurf und noch nicht rechtlich freigegeben. Verbindlich ist bis dahin nur, was im Einzelfall schriftlich oder im Portal ausdrücklich vereinbart wird."}
        </p>
      </div>
    </aside>
  );
}

/** Verweise auf die übrigen Bedingungen und die allgemeinen Rechtstexte (Seitenende). */
export function WeitereBedingungen({ pfad, stand = STAND_BEDINGUNGEN }) {
  return (
    <>
      <h2>Verhältnis zu anderen Regelungen, Stand</h2>
      <p>
        Ergänzend gelten die <Link href="/nutzungsbedingungen">Nutzungsbedingungen</Link> der Plattform; bei Widersprüchen gehen diese
        besonderen Bedingungen vor, individuelle schriftliche Vereinbarungen gehen beiden vor. Wie wir personenbezogene Daten verarbeiten,
        beschreibt die <Link href="/datenschutz">Datenschutzerklärung</Link>. Stand: {stand}.
      </p>
      <nav aria-label="Weitere besondere Bedingungen" className="mt-8 rounded-2xl bg-sand-50 p-5 ring-1 ring-ink-200/60">
        <p className="font-display text-[15.5px] font-bold text-ink-900">Weitere besondere Bedingungen</p>
        <ul className="mt-2 space-y-1 text-[15px]">
          {BEDINGUNGEN.filter((b) => b.href !== pfad).map((b) => (
            <li key={b.href}>
              <Link href={b.href}>{b.titel}</Link>
            </li>
          ))}
        </ul>
      </nav>
    </>
  );
}
// src/app/bedingungen/banken/page.js
//
// Vertraulichkeitsbedingungen für Banken (Bank-Portal, Bankenpaket) –
// ENTWURF zur anwaltlichen Prüfung, noindex bis zur Freigabe (siehe
// ../_teile.js). Fachgrundlage: docs/FINANZIERUNG.md, docs/PLATTFORM.md
// (Bank-Portal: Einladung mit persönlichem Link, nur freigegebene Bausteine,
// Abrufe protokolliert). Offene Punkte: Dauer der Vertraulichkeit,
// Weitergabe an Refinanzierer/Förderbanken, Verhältnis zu bankeigenen NDAs.

import LegalShell from "@/components/Reusable/LegalShell";
import { GESELLSCHAFT } from "@/data/site";
import { EntwurfHinweis, Platzhalter, WeitereBedingungen, bedingungenMetadata, STAND_BEDINGUNGEN } from "../_teile";

const PFAD = "/bedingungen/banken";

export const metadata = bedingungenMetadata({
  pfad: PFAD,
  titel: "Vertraulichkeitsbedingungen Banken | ÖkoInvest",
  beschreibung:
    "Entwurf der Vertraulichkeitsbedingungen für Banken im Bank-Portal: Nutzung des Bankenpakets, zulässige Weitergabe, Zugang, Protokoll, Datenschutz und Dauer.",
  bild: "/img/team-praesentation.jpg",
  bildAlt: "Team bei einer Präsentation",
});

const G = GESELLSCHAFT;

export default function VertraulichkeitBankenPage() {
  return (
    <LegalShell
      titel="Vertraulichkeitsbedingungen für Banken"
      pfad={PFAD}
      stand={STAND_BEDINGUNGEN}
      lead="Regeln für Banken und Finanzierungspartner, die im Bank-Portal Finanzierungsanfragen der ÖkoInvest-Gruppe prüfen und das Bankenpaket abrufen."
    >
      <EntwurfHinweis />

      <h2>§ 1 Geltung und Zugang</h2>
      <p>
        (1) Die {G.name} bzw. die jeweilige Projektgesellschaft („Anfragende“) lädt Banken über einen persönlichen, befristeten Link zu einer
        Finanzierungsanfrage ein. Mit dem ersten Abruf von Unterlagen erkennt die Bank diese Bedingungen an. Bestehende oder später
        abgeschlossene individuelle Vertraulichkeitsvereinbarungen gehen vor.
      </p>
      <p>
        (2) Der Zugang ist persönlich und an die eingeladene E-Mail-Adresse gebunden. Zugangsdaten und Links dürfen nicht weitergegeben werden;
        weitere Personen der Bank werden auf Anforderung eingeladen. Die Bank teilt mit, wenn eine berechtigte Person ausscheidet.
      </p>

      <h2>§ 2 Vertrauliche Informationen</h2>
      <p>
        Vertraulich sind alle Informationen, die der Bank im Zusammenhang mit der Anfrage zugänglich werden – insbesondere das{" "}
        <strong>Bankenpaket</strong> (Projektsteckbrief, Finanzmodell, Ertragsgutachten, Verträge, Genehmigungen, Grundbuch- und
        Dienstbarkeitsunterlagen), Rückfragen und Antworten sowie die Tatsache der Anfrage selbst. Ausgenommen sind Informationen, die öffentlich
        bekannt sind oder werden, ohne dass die Bank dies zu vertreten hat, die der Bank nachweislich bereits bekannt waren oder die sie
        rechtmäßig von Dritten ohne Vertraulichkeitspflicht erhalten hat.
      </p>

      <h2>§ 3 Zweckbindung und zulässige Weitergabe</h2>
      <p>
        (1) Die Bank nutzt die Informationen ausschließlich zur Prüfung, Strukturierung, Entscheidung und Durchführung der angefragten
        Finanzierung.
      </p>
      <p>(2) Eine Weitergabe ist nur zulässig an</p>
      <ul>
        <li>Organe, Mitarbeitende und Kreditgremien der Bank und ihrer Konzerngesellschaften, soweit sie die Informationen benötigen,</li>
        <li>zur Verschwiegenheit verpflichtete Berater, Gutachter und Prüfer der Bank,</li>
        <li>
          potenzielle Konsortialbanken, Förder- und Refinanzierungsinstitute sowie Kreditversicherer – nur nach vorheriger Zustimmung der
          Anfragenden und bei gleichwertiger Vertraulichkeitspflicht,
        </li>
        <li>Aufsichtsbehörden, Gerichte und Behörden, soweit die Bank rechtlich dazu verpflichtet ist.</li>
      </ul>
      <p>
        Die Bank stellt sicher, dass Empfänger dieselben Pflichten einhalten. Bankgeheimnis und bankrechtliche Pflichten bleiben unberührt.
      </p>

      <h2>§ 4 Kennzeichnung und Protokoll</h2>
      <p>
        Jeder Abruf von Unterlagen wird mit Person und Zeitpunkt protokolliert. Unterlagen können den Namen des Empfängers tragen. Die Bank
        entfernt solche Kennzeichnungen nicht und lädt Unterlagen nicht automatisiert oder massenhaft herunter.
      </p>

      <h2>§ 5 Personenbezogene Daten</h2>
      <p>
        (1) Das Bankenpaket kann personenbezogene Daten Dritter enthalten, etwa von Flächen- und Dacheigentümern (Pacht- und
        Dienstbarkeitsverträge, Grundbuchauszüge) oder Stromabnehmern. Die Anfragenden geben nur weiter, was für Kreditentscheidung und
        Besicherung erforderlich ist.
      </p>
      <p>
        (2) Die Bank verarbeitet diese Daten als eigener Verantwortlicher nur für den Zweck nach § 3, schützt sie durch angemessene technische
        und organisatorische Maßnahmen und löscht sie, sobald sie nicht mehr benötigt werden und keine Aufbewahrungspflicht besteht. Anfragen
        betroffener Personen, die die Anfragenden betreffen, leitet sie weiter.
      </p>

      <h2>§ 6 Unverbindlichkeit</h2>
      <p>
        (1) Die Anfrage ist keine Zusage, mit der Bank abzuschließen. Die Anfragenden sind frei, mehrere Banken anzufragen und Angebote abzulehnen.
        Term Sheets gelten als indikativ, sofern sie nicht ausdrücklich als verbindlich bezeichnet sind.
      </p>
      <p>
        (2) Kosten der Prüfung trägt jede Seite selbst, soweit nicht schriftlich anders vereinbart (z. B. Bearbeitungsentgelt im Term Sheet).
      </p>

      <h2>§ 7 Keine Gewähr</h2>
      <p>
        Die Informationen werden nach bestem Wissen bereitgestellt. Finanzmodelle und Prognosen beruhen auf Annahmen mit Stand; eine Gewähr für
        Vollständigkeit, Richtigkeit oder den Eintritt von Prognosen übernehmen die Anfragenden nur im Rahmen des späteren Kreditvertrags. Die
        Bank nimmt ihre eigene Prüfung vor.
      </p>

      <h2>§ 8 Rückgabe, Löschung und Dauer</h2>
      <p>
        (1) Kommt keine Finanzierung zustande, löscht die Bank auf Anforderung die erhaltenen Unterlagen bzw. gibt sie zurück; ausgenommen sind
        Kopien, die sie aufgrund gesetzlicher oder aufsichtsrechtlicher Pflichten aufbewahren muss, und automatische Sicherungskopien – für diese
        gilt die Vertraulichkeit fort.
      </p>
      <p>
        (2) Die Pflichten gelten für die Dauer der Anfrage und darüber hinaus für{" "}
        <Platzhalter>z. B. 3 Jahre nach Ende der Anfrage bzw. für die Laufzeit eines Kreditverhältnisses</Platzhalter>.
      </p>
      <p>
        (3) Die Anfragenden können den Zugang jederzeit beenden, insbesondere nach Abschluss der Anfrage oder bei Verstößen gegen diese
        Bedingungen.
      </p>

      <WeitereBedingungen pfad={PFAD} />
    </LegalShell>
  );
}

// src/app/nutzungsbedingungen/page.js
//
// Nutzungsbedingungen für Website, Portal und Projektbörse der ÖkoInvest GmbH.
//
// ENTWURF ZUR ANWALTLICHEN PRÜFUNG – der sichtbare Hinweis oben auf der Seite
// bleibt stehen, bis die Fassung freigegeben ist (ENTWURF = false setzen).
// Offene Punkte für die Prüfung:
//  - Umgehungsschutz: Dauer (hier 24 Monate) und Höhe mit der
//    Provisionsvereinbarung abstimmen (siehe /bedingungen/projektboerse).
//  - Aufsichtsrecht: Abgrenzung Vermittlung von Projektrechten/Gesellschafts-
//    anteilen gegenüber Wertpapier-/Anlagevermittlung (WAG 2018, AltFG,
//    KMG 2019; DE: KWG/WpIG, § 34c/§ 34f GewO) prüfen.
//  - Maklerrecht (MaklerG AT) und Gewerbeberechtigung prüfen; Energie-
//    beschaffung: Abgrenzung zu Energievermittlung/-beratung (Gewerbe,
//    ggf. Registrierung), Vergaberecht bei öffentlichen Auftraggebern.
//  - Geldwäsche: Verpflichtetenstellung (GwG DE, GewO/FM-GwG AT, GwG CH,
//    AMLR ab 10.07.2027) – bestimmt, ob KYC Pflicht oder Vertragsbedingung ist.
//  - Einfache elektronische Signatur: Beweiswert und Einsatzgrenzen (§ 10).
//  - Verbraucher: Mitglieder/Bürger können Verbraucher sein – Klauseln zu
//    Haftung, Änderungen und Gerichtsstand gegen KSchG/§§ 305 ff. BGB prüfen.
//  - Gerichtsstand konkret benennen.

import Link from "next/link";
import { AlertTriangle } from "lucide-react";
import LegalShell from "@/components/Reusable/LegalShell";
import { GESELLSCHAFT, abs } from "@/data/site";
import { PROVISION } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";

const ENTWURF = true;

const PAGE_URL = abs("/nutzungsbedingungen");
const TITEL = "Nutzungsbedingungen Plattform & Projektbörse | ÖkoInvest";
const BESCHREIBUNG =
  "Nutzungsbedingungen der ÖkoInvest-Plattform: Rollen, Deal-Room, Bieterverfahren, Energiebeschaffung, Signatur, KYC, Provision nur bei Abschluss und Haftung.";

/** Datum der Fassung */
const STAND = "30. September 2026";

export const metadata = {
  title: TITEL,
  description: BESCHREIBUNG,
  alternates: { canonical: PAGE_URL },
  robots: { index: true, follow: true },
  openGraph: {
    type: "website",
    locale: "de_AT",
    url: PAGE_URL,
    siteName: "ÖkoInvest",
